"use client";

import { useState, useEffect, useRef } from "react";
import { 
  MessageSquare, 
  Play, 
  Pause, 
  RotateCcw, 
  UserPlus, 
  CheckCircle2, 
  AlertCircle,
  Clock,
  Zap,
  ArrowRight
} from "lucide-react";
import PersonaCard from "@/components/PersonaCard";
import type { Persona, DebateMessage, StreamEvent } from "@/types";

export default function DebateArenaPage() {
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [topic, setTopic] = useState("");
  const [rounds, setRounds] = useState(3);
  const [isRunning, setIsRunning] = useState(false);
  const [messages, setMessages] = useState<DebateMessage[]>([]);
  const [currentStreamingMessage, setCurrentStreamingMessage] = useState<{
    personaId: string;
    personaName: string;
    content: string;
    round: number;
  } | null>(null);
  const [summary, setSummary] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, currentStreamingMessage]);

  useEffect(() => {
    fetch("/api/personas")
      .then(res => res.json())
      .then(data => {
        if (data.success) setPersonas(data.data);
      });
  }, []);

  const handleSelectPersona = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(prev => prev.filter(i => i !== id));
    } else {
      if (selectedIds.length < 3) {
        setSelectedIds(prev => [...prev, id]);
      }
    }
  };

  const startDebate = async () => {
    if (!topic || selectedIds.length < 2) return;

    setIsRunning(true);
    setMessages([]);
    setCurrentStreamingMessage(null);
    setSummary(null);
    setError(null);

    try {
      const response = await fetch("/api/debate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          topic,
          personaIds: selectedIds,
          rounds
        })
      });

      if (!response.body) throw new Error("No response body");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n\n");
        buffer = lines.pop() || "";

        for (const line of lines) {
          if (!line.startsWith("data: ")) continue;
          
          try {
            const event: StreamEvent = JSON.parse(line.slice(6));
            
            switch (event.type) {
              case "start":
                console.log("Debate started");
                break;
              case "message_start":
                setCurrentStreamingMessage({
                  personaId: event.personaId,
                  personaName: event.personaName,
                  content: "",
                  round: event.round
                });
                break;
              case "message_chunk":
                setCurrentStreamingMessage(prev => prev ? {
                  ...prev,
                  content: prev.content + event.chunk
                } : null);
                break;
              case "message_end":
                setMessages(prev => [...prev, event.message]);
                setCurrentStreamingMessage(null);
                break;
              case "debate_end":
                setSummary(event.summary);
                setIsRunning(false);
                break;
              case "error":
                setError(event.error);
                setIsRunning(false);
                break;
            }
          } catch (e) {
            console.error("Failed to parse event:", e);
          }
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start debate");
      setIsRunning(false);
    }
  };

  const resetDebate = () => {
    setIsRunning(false);
    setMessages([]);
    setCurrentStreamingMessage(null);
    setSummary(null);
    setError(null);
  };

  return (
    <div className="min-h-full flex h-screen">
      {/* Configuration Sidebar */}
      <div 
        className="w-96 h-full border-r flex flex-col p-6 overflow-y-auto scroll-thin"
        style={{ background: "var(--bg-secondary)", borderRight: "1px solid var(--border-subtle)" }}
      >
        <div className="flex items-center gap-2 mb-8">
          <div className="p-2 rounded-xl bg-amber-400/10 text-amber-400">
            <Zap size={20} />
          </div>
          <h1 className="font-display text-2xl font-bold">Debate Arena</h1>
        </div>

        {!isRunning && !messages.length ? (
          <div className="space-y-8 animate-fade-in">
            {/* Step 1: Topic */}
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider mb-3" style={{ color: "var(--text-muted)" }}>
                Step 1: Define Topic
              </label>
              <textarea 
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="What should they debate? E.g. 'Is a subscription model better than one-time purchase for a productivity app?'"
                rows={4}
                className="w-full rounded-xl px-4 py-3 text-sm resize-none outline-none"
                style={{ background: "var(--bg-elevated)", border: "1px solid var(--border-default)", color: "var(--text-primary)" }}
              />
            </div>

            {/* Step 2: Personas */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <label className="block text-xs font-semibold uppercase tracking-wider" style={{ color: "var(--text-muted)" }}>
                  Step 2: Select Personas
                </label>
                <span className="text-[10px] font-mono px-2 py-0.5 rounded-full bg-white/5" style={{ color: "var(--text-muted)" }}>
                  {selectedIds.length}/3 SELECTED
                </span>
              </div>
              <div className="grid grid-cols-1 gap-3">
                {personas.map(p => (
                  <div 
                    key={p.id}
                    onClick={() => handleSelectPersona(p.id)}
                    className="group relative rounded-xl p-3 cursor-pointer transition-all border"
                    style={{ 
                      background: selectedIds.includes(p.id) ? "rgba(251, 191, 36, 0.05)" : "var(--bg-elevated)",
                      borderColor: selectedIds.includes(p.id) ? "var(--amber-400)" : "var(--border-subtle)"
                    }}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-white/5 font-bold text-xs">
                        {p.name.charAt(0)}
                      </div>
                      <div className="min-w-0">
                        <div className="text-xs font-bold truncate">{p.name}</div>
                        <div className="text-[10px]" style={{ color: "var(--text-muted)" }}>{p.occupation}</div>
                      </div>
                    </div>
                    {selectedIds.includes(p.id) && (
                      <CheckCircle2 size={14} className="absolute top-3 right-3 text-amber-400" />
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Step 3: Rounds */}
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider mb-3" style={{ color: "var(--text-muted)" }}>
                Step 3: Duration
              </label>
              <div className="flex items-center gap-2">
                {[1, 2, 3, 5].map(r => (
                  <button
                    key={r}
                    onClick={() => setRounds(r)}
                    className="flex-1 py-2 rounded-lg text-xs font-medium border transition-all"
                    style={{ 
                      background: rounds === r ? "rgba(251, 191, 36, 0.1)" : "transparent",
                      borderColor: rounds === r ? "var(--amber-400)" : "var(--border-subtle)",
                      color: rounds === r ? "var(--amber-400)" : "var(--text-secondary)"
                    }}
                  >
                    {r} {r === 1 ? 'Round' : 'Rounds'}
                  </button>
                ))}
              </div>
            </div>

            <button
              onClick={startDebate}
              disabled={!topic || selectedIds.length < 2}
              className="w-full py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all disabled:opacity-40"
              style={{ background: "var(--amber-400)", color: "black", boxShadow: "0 8px 20px rgba(251, 191, 36, 0.2)" }}
            >
              <Play size={16} fill="currentColor" />
              Launch Simulation
            </button>
          </div>
        ) : (
          <div className="space-y-6 animate-fade-in">
            <div className="p-4 rounded-2xl" style={{ background: "var(--bg-elevated)", border: "1px solid var(--border-default)" }}>
              <div className="text-[10px] font-mono mb-2" style={{ color: "var(--text-muted)" }}>CURRENT TOPIC</div>
              <p className="text-sm font-medium leading-relaxed">{topic}</p>
            </div>

            <div className="space-y-3">
              <div className="text-[10px] font-mono" style={{ color: "var(--text-muted)" }}>PARTICIPANTS</div>
              {selectedIds.map(id => {
                const p = personas.find(x => x.id === id);
                if (!p) return null;
                const isActive = currentStreamingMessage?.personaId === id;
                return (
                  <div 
                    key={id} 
                    className="flex items-center gap-3 p-3 rounded-xl border transition-all"
                    style={{ 
                      background: isActive ? "rgba(251, 191, 36, 0.05)" : "rgba(255,255,255,0.02)",
                      borderColor: isActive ? "var(--amber-400)" : "var(--border-subtle)"
                    }}
                  >
                    <div className="w-8 h-8 rounded-lg bg-white/5 flex items-center justify-center font-bold text-xs">
                      {p.name.charAt(0)}
                    </div>
                    <div className="flex-1">
                      <div className="text-xs font-bold">{p.name}</div>
                      <div className="text-[10px]" style={{ color: "var(--text-muted)" }}>{isActive ? "Thinking..." : "Listening"}</div>
                    </div>
                    {isActive && <div className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />}
                  </div>
                );
              })}
            </div>

            <div className="flex gap-2">
              <button 
                onClick={resetDebate}
                className="flex-1 py-3 rounded-xl text-xs font-semibold border border-white/10 hover:bg-white/5 transition-all"
              >
                Reset Arena
              </button>
              {summary && (
                <button 
                  className="flex-1 py-3 rounded-xl text-xs font-semibold bg-white/10 hover:bg-white/20 transition-all"
                >
                  Save Results
                </button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Main Arena Display */}
      <div className="flex-1 h-full flex flex-col relative overflow-hidden bg-[#0d0a08]">
        {/* Arena Header */}
        <div className="h-14 border-b flex items-center px-8 justify-between z-10" style={{ background: "rgba(13,10,8,0.8)", backdropFilter: "blur(8px)", borderColor: "var(--border-subtle)" }}>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 text-xs" style={{ color: "var(--text-muted)" }}>
              <Clock size={14} />
              <span>Session: {isRunning ? "Live" : messages.length ? "Completed" : "Standby"}</span>
            </div>
            {messages.length > 0 && (
              <>
                <div className="w-1 h-1 rounded-full bg-white/20" />
                <div className="text-xs" style={{ color: "var(--text-muted)" }}>
                  {messages.length} exchanges
                </div>
              </>
            )}
          </div>
          {isRunning && (
            <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-red-500/10 text-red-500 text-[10px] font-bold uppercase tracking-widest animate-pulse">
              <div className="w-1.5 h-1.5 rounded-full bg-red-500" />
              Simulating
            </div>
          )}
        </div>

        {/* Message Stream */}
        <div className="flex-1 overflow-y-auto p-8 space-y-8 scroll-thin relative">
          {!messages.length && !currentStreamingMessage ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center opacity-20 grayscale">
              <MessageSquare size={80} strokeWidth={1} />
              <p className="mt-4 font-display text-xl tracking-widest">AWAITING INPUT</p>
            </div>
          ) : (
            <div className="max-w-3xl mx-auto space-y-10">
              {messages.map((m, idx) => (
                <div key={m.id || idx} className="animate-fade-in">
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-6 h-6 rounded bg-white/5 flex items-center justify-center text-[10px] font-bold">
                      {m.personaName.charAt(0)}
                    </div>
                    <span className="text-[11px] font-bold uppercase tracking-wider" style={{ color: "var(--text-muted)" }}>
                      {m.personaName} <span className="opacity-40 ml-2">Round {m.round}</span>
                    </span>
                  </div>
                  <div className="debate-bubble complete text-sm leading-relaxed whitespace-pre-wrap">
                    {m.content}
                  </div>
                </div>
              ))}

              {currentStreamingMessage && (
                <div className="animate-fade-in">
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-6 h-6 rounded bg-amber-400/10 text-amber-400 flex items-center justify-center text-[10px] font-bold">
                      {currentStreamingMessage.personaName.charAt(0)}
                    </div>
                    <span className="text-[11px] font-bold uppercase tracking-wider text-amber-400">
                      {currentStreamingMessage.personaName} <span className="opacity-40 ml-2">Round {currentStreamingMessage.round}</span>
                    </span>
                  </div>
                  <div className="debate-bubble active text-sm leading-relaxed streaming-cursor whitespace-pre-wrap">
                    {currentStreamingMessage.content}
                  </div>
                </div>
              )}

              {summary && (
                <div className="animate-fade-in p-8 rounded-2xl border" style={{ background: "rgba(251, 191, 36, 0.03)", borderColor: "rgba(251, 191, 36, 0.2)" }}>
                  <h3 className="font-display text-2xl font-bold mb-4 text-amber-400">Debate Insights</h3>
                  <div className="prose-dark text-sm leading-relaxed whitespace-pre-wrap opacity-90">
                    {typeof summary === 'string' ? summary : JSON.stringify(summary, null, 2)}
                  </div>
                  <button className="mt-8 flex items-center gap-2 text-sm font-bold text-amber-400 group">
                    Generate Full Market Report
                    <ArrowRight size={14} className="group-hover:translate-x-1 transition-transform" />
                  </button>
                </div>
              )}
              
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {error && (
          <div className="mx-8 mb-8 p-4 rounded-xl flex items-center gap-3 bg-red-500/10 border border-red-500/20 text-red-500 text-sm">
            <AlertCircle size={18} />
            {error}
          </div>
        )}
      </div>
    </div>
  );
}
